{
  "name": "@remvn/opencode-notify",
  "version": "0.2.0",
  "description": "OpenCode plugin that sends system notifications and plays sounds when permission is needed, generation completes, or errors occur",
  "license": "MIT",
  "type": "module",
  "exports": {
    "./server": "./src/index.ts",
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "dist"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/remvn/opencode-notify.git"
  },
  "bugs": {
    "url": "https://github.com/remvn/opencode-notify/issues"
  },
  "homepage": "https://github.com/remvn/opencode-notify#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "notifications",
    "windows",
    "wsl"
  ],
  "scripts": {
    "lint": "tsc --noEmit",
    "test": "bun test src/test/plugin.test.ts src/test/plugin-loading.test.ts",
    "notify-test": "bun run ./src/test/notify.test.ts",
    "publish": "npm publish --access public",
    "prepublishOnly": "bun run lint"
  },
  "dependencies": {
    "@opencode/plugin": "2.1.4",
    "dayjs": "^1.11.23"
  },
  "devDependencies": {
    "@types/bun": "^1.3.12",
    "@types/node": "^25.6.0",
    "typescript": "^5.0.0"
  }
}
